INSERT INTO public."activities" ("id", "title", "slug", "date", "content", "image", "created_at", "updated_at", "summary", "category", "video_url", "description") VALUES (2, 'Regional Agricultural Machinery Field Excursion', 'regional-agricultural-machinery-field-excursion', 'June 2026', 'Documenting field operations, tractor demonstrations, and technical machinery excursions across farming communities.', '["\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.21 PM.jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.28 PM (1).jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.28 PM.jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.29 PM (1).jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.29 PM (2).jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.29 PM.jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.30 PM (1).jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.30 PM (2).jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.30 PM.jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.31 PM (1).jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.31 PM.jpeg","\/assets\/gallery\/EXCURSION\/WhatsApp Image 2026-07-13 at 3.17.32 PM.jpeg"]', '2026-07-13 14:52:48', '2026-07-13 14:52:48', 'Documenting field operations, tractor demonstrations, and technical machinery excursions across farming communities.', 'Excursion', NULL, 'Documenting field operations, tractor demonstrations, and technical machinery excursions across farming communities.') ON CONFLICT (id) DO NOTHING;
